using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
internal sealed class OpticalBackdrop {}
internal static class LiveGlassBackdrop {internal static OpticalBackdrop Attach(Func<Form> form,WebView2 view){return null;}}
internal sealed class PointerFixtureForm:Form {protected override bool ShowWithoutActivation{get{return true;}}}
internal static class TestGlassPointerMotion {
 [DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr context);
 static Form form;static WebView2 view;static string root,output;static bool painted,dockMode;static DockPlate plate;static Region widgetRegion=new Region(Rectangle.Empty);static float[][] dockOutline;static Rectangle dockBounds;static readonly JavaScriptSerializer json=new JavaScriptSerializer();static readonly Stopwatch clock=Stopwatch.StartNew();static DesktopPointerDelivery delivery;
 static readonly List<double> regionTimes=new List<double>(),ackTimes=new List<double>();static readonly Dictionary<int,double> sent=new Dictionary<int,double>();
 static void Clip(){var region=widgetRegion.Clone();if(dockOutline!=null)using(var path=new GraphicsPath()){path.AddPolygon(dockOutline.Select(p=>new PointF(p[0]+dockBounds.X-26,p[1]+dockBounds.Y-26)).ToArray());using(var clip=GlassWindow.Clip(path,form.ClientRectangle))region.Union(clip);}var old=form.Region;form.Region=region;if(old!=null)old.Dispose();}
 static Task<string> Eval(string script){return view.CoreWebView2.ExecuteScriptAsync(script);}
 static void Send(object value){view.CoreWebView2.PostWebMessageAsJson(json.Serialize(value));}
 static double P(List<double> values,double p){if(values.Count==0)return 0;var sorted=values.OrderBy(v=>v).ToArray();return sorted[Math.Min(sorted.Length-1,(int)Math.Floor(sorted.Length*p))];}
 static async Task Run(){
  await view.EnsureCoreWebView2Async(await CoreWebView2Environment.CreateAsync(null,Path.Combine(root,"runtime")));await new WebViewPixelScale(view,null).SyncAsync(true);
  view.CoreWebView2.SetVirtualHostNameToFolderMapping("desktop.local",root,CoreWebView2HostResourceAccessKind.DenyCors);
  await view.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync("window.probe={frames:[],errors:[]};addEventListener('error',e=>probe.errors.push(e.message));const get=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(...args){const gl=get.apply(this,args);if(gl&&args[0]==='webgl'&&!gl.__probe){gl.__probe=true;const clear=gl.clear.bind(gl);gl.clear=(...args)=>{probe.frames.push(performance.now());return clear(...args)}}return gl};");
  delivery=new DesktopPointerDelivery(packet=>{var p=(DesktopPointerDelivery.Packet)packet;sent[p.sequence]=clock.Elapsed.TotalMilliseconds;Send(p);});
  view.CoreWebView2.WebMessageReceived+=(s,e)=>{
   string value=e.TryGetWebMessageAsString();if(value=="painted")painted=true;
   if(value.StartsWith("pointer-ack:")){int sequence=Int32.Parse(value.Substring(12));double start;if(sent.TryGetValue(sequence,out start)){ackTimes.Add(clock.Elapsed.TotalMilliseconds-start);sent.Remove(sequence);}delivery.Acknowledge(sequence);}
   if(value.StartsWith("dock-shape:")&&dockMode){var watch=Stopwatch.StartNew();dockOutline=json.Deserialize<float[][]>(value.Substring(11));plate.Outline(dockOutline);Clip();regionTimes.Add(watch.Elapsed.TotalMilliseconds);}
   if(value.StartsWith("widget-shapes:")){var watch=Stopwatch.StartNew();var shapes=json.Deserialize<float[][][]>(value.Substring(14));widgetRegion.MakeEmpty();foreach(var shape in shapes)if(shape.Length>2)using(var path=new GraphicsPath()){path.AddPolygon(shape.Select(p=>new PointF(p[0],p[1])).ToArray());using(var clip=GlassWindow.Clip(path,form.ClientRectangle))widgetRegion.Union(clip);}Clip();regionTimes.Add(watch.Elapsed.TotalMilliseconds);}
  };
  view.Source=new Uri("https://desktop.local/index.html");for(int i=0;i<100&&view.CoreWebView2.Source!="https://desktop.local/index.html";i++)await Task.Delay(20);await Task.Delay(350);await new WebViewPixelScale(view,null).SyncAsync(true);
  var cards=new List<object>{new{name="System",x=60,y=80,w=630,h=210,r=24},new{name="Clock",x=950,y=80,w=305,h=245,r=24},new{name="Calendar",x=950,y=380,w=305,h=245,r=24},new{name="Moon",x=1300,y=80,w=305,h=245,r=24},new{name="YearDots",x=1300,y=380,w=305,h=245,r=24}};
  if(dockMode){dockBounds=new Rectangle(131,form.ClientSize.Height-149,form.ClientSize.Width-262,130);cards.Add(new{name="Dock",x=dockBounds.X,y=dockBounds.Y+16,w=dockBounds.Width,h=dockBounds.Height-16,r=34,insetY=16});plate=new DockPlate();plate.Sync(form.Handle,form.Handle,new Rectangle(form.Left+dockBounds.X,form.Top+dockBounds.Y,dockBounds.Width,dockBounds.Height),form.Bounds);}
  Send(new{type="layout",width=form.ClientSize.Width,height=form.ClientSize.Height,theme="Sky",paused=false,cards=cards});Send(new{type="preferences",snapshot=new{glassStyle="J",glassOverrides=new{J=new{refraction=1.37}},liveGlassBackground=false,reducedMotion=false}});
  for(int i=0;i<100&&!painted;i++)await Task.Delay(20);if(!painted)throw new Exception("Renderer did not paint");await Task.Delay(300);
  string edge=await Eval(File.ReadAllText(Path.Combine(root,"edge-probe.js")));if(edge=="null")throw new Exception("Edge flow pixel check failed");
  regionTimes.Clear();ackTimes.Clear();await Eval("probe.frames=[]");
  var sweep=Stopwatch.StartNew();using(var timer=new Timer{Interval=8}){timer.Tick+=(s,e)=>{double t=sweep.Elapsed.TotalSeconds;delivery.Offer(dockMode?new Point(form.ClientSize.Width/2+(int)((dockBounds.Width/2-99)*Math.Sin(t*6)),dockBounds.Y+79+(int)(35*Math.Cos(t*5))):new Point(375+(int)(270*Math.Sin(t*6)),185+(int)(70*Math.Cos(t*5))),false);};timer.Start();await Task.Delay(4000);timer.Stop();}
  string browser=await Eval("(()=>{const f=probe.frames,g=f.slice(1).map((x,i)=>x-f[i]).sort((a,b)=>a-b);return{frames:f.length,p50GapMs:g[Math.floor(g.length*.5)],p95GapMs:g[Math.floor(g.length*.95)],over33:g.filter(x=>x>33).length,errors:probe.errors}})()");
  var result=new{browser=json.DeserializeObject(browser),edgeFlow=json.DeserializeObject(edge),acknowledgements=ackTimes.Count,ackP50Ms=P(ackTimes,.5),ackP95Ms=P(ackTimes,.95),regionUpdates=regionTimes.Count,regionP50Ms=P(regionTimes,.5),regionP95Ms=P(regionTimes,.95),presentationMeasured=false,canvas=new{width=form.ClientSize.Width,height=form.ClientSize.Height}};File.WriteAllText(output,json.Serialize(result));
  if(ackTimes.Count<40||!browser.Contains("\"errors\":[]"))throw new Exception("Pointer delivery or browser errors");
  delivery.Offer(new Point(-999,-999),false);await Task.Delay(1200);
  // The broad native envelope must leave the actual shader corner transparent.
  string alpha=await Eval("(()=>{const c=document.querySelector('#scene'),g=c.getContext('webgl'),p=new Uint8Array(4);g.readPixels(40,c.height-60,1,1,g.RGBA,g.UNSIGNED_BYTE,p);const outside=p[3];g.readPixels(375,c.height-185,1,1,g.RGBA,g.UNSIGNED_BYTE,p);return outside===0&&p[3]>200})()");if(alpha!="true")throw new Exception("Glass body or transparent envelope coverage changed");
 }
 [STAThread]static int Main(string[] args){root=args[0];output=args[1];dockMode=args.Length>2&&args[2]=="dock";SetProcessDpiAwarenessContext(new IntPtr(-4));Application.EnableVisualStyles();form=new PointerFixtureForm{Text="PrismGlass · isolated pointer check",FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Bounds=Screen.PrimaryScreen.Bounds,ShowInTaskbar=false,TopMost=true};view=new WebView2{Dock=DockStyle.Fill,DefaultBackgroundColor=Color.Transparent};form.Controls.Add(view);GlassWindow.Configure(form,view);int result=0;form.Shown+=async(s,e)=>{try{await Run();}catch(Exception ex){File.WriteAllText(output+".error",ex.ToString());result=1;}finally{if(plate!=null)plate.Dispose();view.Dispose();form.Close();widgetRegion.Dispose();}};Application.Run(form);return result;}
}
